What is the most efficient way to compare two pieces of text in C++ to determine their overall sentiment and emotional tone? For example, how would I compare the phrases "I feel happy today" and "This is the worst day ever" to determine their emotional polarity? Can you provide me with a sample C++ code to perform this task? 
[C++ code]
#include <iostream>
#include <string>
#include <algorithm>
#include <vector>
#include <fstream>
bool isPositive(std::string str) {
    std::vector<std::string> positiveWords;
    std::string word;
    std::ifstream infile("positive_words.txt"); //file containing list of positive words
    while (infile >> word) {
        positiveWords.push_back(word);
    }
    // Convert string to lowercase
    std::transform(str.begin(), str.end(), str.begin(), ::tolower);
    // Remove punctuation
    str.erase(std::remove_if(str.begin(), str.end(), ::ispunct), str.end());
    // Split into words
    std::istringstream iss(str);
    std::vector<std::string> words((std::istream_iterator<std::string>(iss)), std::istream_iterator<std::string>());
    // Check for positive words
    int count = 0;
    for (auto word : words) {
        if (std::find(positiveWords.begin(), positiveWords.end(), word) != positiveWords.end()) {
            count++;
        }
    }
    // Determine overall sentiment
    if (count > words.size() / 2) {
        return true;
    }
    else {
        return false;
    }
}
int main() {
    std::string str1 = "I feel happy today";
    std::string str2 = "This is the worst day ever";
    if (isPositive(str1)) {
        std::cout << "The first string has a positive emotional tone." << std::endl;
    }
    else {
        std::cout << "The first string has a negative emotional tone." << std::endl;
    }
    if (isPositive(str2)) {
        std::cout << "The second string has a positive emotional tone." << std::endl;
    }
    else {
        std::cout << "The second string has a negative emotional tone." << std::endl;
    }
    return 0;
}

