```
import pandas as pd
import numpy as np
# create sample data
data = {'Name': ['Alice', 'Bob', 'Charlie', 'David', 'Emma', 'Frank'],
        'Dietary Restriction': ['Vegetarian', 'Kosher', 'Gluten-free', 'Vegetarian', 'Halal', 'Kosher'],
        'Preferred Seat': ['Corner', 'Middle', 'Middle', 'Corner', 'Middle', 'Corner']}
guest_seating = pd.DataFrame(data)
# define table dimensions
num_rows = 3
num_cols = 4
# create empty seating chart
seating_chart = np.empty((num_rows, num_cols), dtype=object)
seating_chart.fill('')
# assign seats based on preferred seat
for index, row in guest_seating.iterrows():
    name = row['Name']
    pref_seat = row['Preferred Seat']
    if pref_seat == 'Corner':
        for i in range(num_rows):
            if i == 0 or i == num_rows - 1:
                for j in range(num_cols):
                    if j == 0 or j == num_cols - 1:
                        if seating_chart[i][j] == '':
                            seating_chart[i][j] = name
                            break
            else:
                if seating_chart[i][0] == '':
                    seating_chart[i][0] = name
                    break
                elif seating_chart[i][num_cols - 1] == '':
                    seating_chart[i][num_cols - 1] = name
                    break
    else:
        for i in range(num_rows):
            for j in range(num_cols):
                if j == num_cols // 2:
                    if seating_chart[i][j] == '':
                        seating_chart[i][j] = name
                        break
# assign seats based on dietary restrictions
for i in range(num_rows):
    for j in range(num_cols):
        if seating_chart[i][j] == '':
            for index, row in guest_seating.iterrows():
                name = row['Name']
                diet = row['Dietary Restriction']
                if diet == 'Vegetarian':
                    if i > 0 and seating_chart[i-1][j] in ['Vegetarian', '']:
                        seating_chart[i][j] = name
                        break
                    elif i < num_rows - 1 and seating_chart[i+1][j] in ['Vegetarian', '']:
                        seating_chart[i][j] = name
                        break
                elif diet == 'Kosher':
                    if j > 0 and seating_chart[i][j-1] in ['Kosher', '']:
                        seating_chart[i][j] = name
                        break
                    elif j < num_cols - 1 and seating_chart[i][j+1] in ['Kosher', '']:
                        seating_chart[i][j] = name
                        break
                elif diet == 'Gluten-free':
                    if i > 0 and seating_chart[i-1][j] in ['Gluten-free', '']:
                        seating_chart[i][j] = name
                        break
                    elif i < num_rows - 1 and seating_chart[i+1][j] in ['Gluten-free', '']:
                        seating_chart[i][j] = name
                        break
                elif diet == 'Halal':
                    if j > 0 and seating_chart[i][j-1] in ['Halal', '']:
                        seating_chart[i][j] = name
                        break
                    elif j < num_cols - 1 and seating_chart[i][j+1] in ['Halal', '']:
                        seating_chart[i][j] = name
                        break
# print seating chart
print(pd.DataFrame(seating_chart))
```
This code creates a sample dataset called "Guest_seating" with columns for each guest's name, dietary restriction, and preferred seat. It then creates an empty seating chart with the specified number of rows and columns. The code then assigns seats based on the guests' preferred seats, filling in the corner seats first and then filling in the middle seats. Finally, it assigns seats based on the guests' dietary restrictions, making sure to minimize the number of guests with a dietary restriction seated next to each other. The resulting seating chart is printed to the console.

