What is the Go code that can query hotel data and filter based on the customer's preference of modern, affordable, and close to tourist spots with a budget of $100/night in Rio de Janeiro?
Here is the Go code that can help you achieve this:
package main
import (
	"fmt"
)
type hotel struct {
	name          string
	location      string
	price         int
	amenities     []string
	distance      float32
	rating        float32
	reviewCount   int
}
func main() {
	hotels := []hotel{
		{name: "Hotel 1", location: "Copacabana", price: 90, amenities: []string{"Pool", "Free breakfast"}, distance: 0.5, rating: 4.2, reviewCount: 100},
		{name: "Hotel 2", location: "Ipanema", price: 120, amenities: []string{"Gym", "Free breakfast"}, distance: 0.3, rating: 4.5, reviewCount: 200},
		{name: "Hotel 3", location: "Botafogo", price: 80, amenities: []string{"Spa", "Free Wi-Fi"}, distance: 0.7, rating: 4.0, reviewCount: 50},
		{name: "Hotel 4", location: "Lapa", price: 110, amenities: []string{"Bar", "Free parking"}, distance: 1.2, rating: 4.3, reviewCount: 150},
		{name: "Hotel 5", location: "Leblon", price: 150, amenities: []string{"Restaurant", "Free breakfast"}, distance: 0.4, rating: 4.6, reviewCount: 300},
	}
	// filter hotels based on criteria
	filteredHotels := []hotel{}
	for _, h := range hotels {
		if h.price <= 100 && h.distance <= 0.5 && contains(h.amenities, "Free Wi-Fi") && contains(h.location, "Rio de Janeiro") {
			filteredHotels = append(filteredHotels, h)
		}
	}
	// sort hotels by rating
	sortByRating(filteredHotels)
	// display top 3 hotels
	fmt.Println("Top 3 hotels that match your preferences:")
	for i := 0; i < 3 && i < len(filteredHotels); i++ {
		fmt.Println(filteredHotels[i])
	}
}
func contains(arr []string, str string) bool {
	for _, a := range arr {
		if a == str {
			return true
		}
	}
	return false
}
func sortByRating(hotels []hotel) {
	for i := 0; i < len(hotels); i++ {
		for j := i + 1; j < len(hotels); j++ {
			if hotels[i].rating < hotels[j].rating {
				hotels[i], hotels[j] = hotels[j], hotels[i]
			}
		}
	}
}

