// Import supply chain data
let path = Bundle.main.path(forResource: "supply_data", ofType: "csv")!
let csv = try! CSV(url: path)
let supplyData = csv.namedRows
// Calculate supplier performance metrics
var supplierMetrics = [String: [String: Any]]()
for row in supplyData {
    let supplier = row["supplier_name"]!
    let deliveredQty = Double(row["delivered_qty"]!)!
    let orderQty = Double(row["order_qty"]!)!
    let leadTime = Double(row["lead_time"]!)!
    let defectQty = Double(row["defect_qty"]!)!
    let receivedQty = Double(row["received_qty"]!)!
    if supplierMetrics[supplier] == nil {
        supplierMetrics[supplier] = [:]
    }
    supplierMetrics[supplier]!["delivery_accuracy"] = deliveredQty / orderQty
    supplierMetrics[supplier]!["lead_time"] = leadTime
    supplierMetrics[supplier]!["defect_rate"] = defectQty / receivedQty
}
// Visualize supplier performance
struct SupplierPerformanceView: View {
    let supplierMetrics: [String: [String: Any]]
    var body: some View {
        VStack {
            Text("Supplier Performance")
                .font(.title)
            Spacer()
            ForEach(Array(supplierMetrics.keys), id: \.self) { supplier in
                let metrics = supplierMetrics[supplier]!
