                        Text(String(format: "%.2f", leadTime))
                        Text("Lead Time")
                    }
                    Spacer()
                    VStack {
                        Text(String(format: "%.2f%%", defectRate * 100))
                        Text("Defect Rate")
                    }
                }
                .padding()
            }
            Spacer()
        }
    }
}
PlaygroundPage.current.setLiveView(SupplierPerformanceView(supplierMetrics: supplierMetrics))
```
