using System;
using System.Collections.Generic;
using System.Text.Json;
class Program
{
    static void Main(string[] args)
    {
        List<int> pounds = new List<int>() { 100, 200, 300, 400, 500 };
        List<Weight> weights = ConvertToKilograms(pounds);
        string json = JsonSerializer.Serialize(new { weights });
        Console.WriteLine(json);
    }
    static List<Weight> ConvertToKilograms(List<int> pounds)
    {
        List<Weight> weights = new List<Weight>();
