Here's the Python function that checks the validity of an IPv4 address and prints its class:
```python
def is_valid_ipv4(ip_address):
    octets = ip_address.split('.')
    if len(octets) != 4:
        return False
    for octet in octets:
        if not octet.isdigit():
            return False
        if octet.startswith('0') and len(octet) > 1:
            return False
        if int(octet) < 0 or int(octet) > 255:
            return False
    if ip_address.endswith('.'):
        return False
    first_octet = int(octets[0])
    if first_octet >= 1 and first_octet <= 126:
        print('Class A')
    elif first_octet >= 128 and first_octet <= 191:
        print('Class B')
    elif first_octet >= 192 and first_octet <= 223:
        print('Class C')
    elif first_octet >= 224 and first_octet <= 239:
        print('Class D')
    elif first_octet >= 240 and first_octet <= 255:
        print('Class E')
    else:
        print('Unknown class')
    return True
```
To check whether the given IP address is valid and print "yes" or "no" accordingly, we can call the function like this:
```python
ip_address = '192.168.0.1'
if is_valid_ipv4(ip_address):
    print('yes')
else:
    print('no')
```
This will output "yes" since the IP address 192.168.0.1 is valid and belongs to Class C.

