                case ChangeType.Deleted:
                    sb.Append(@"\textcolor{blue}{-" + line.Text + "}");
                    break;
                default:
                    sb.Append(line.Text);
                    break;
            }
        }
        Console.WriteLine(sb.ToString());
    }
}
