            List<TextDocumentInput> documents = data.Select(row => new TextDocumentInput
            {
                Id = row[0],
                Text = row[1]
            }).ToList();
            var sentimentBatchResult = client.SentimentBatchAsync(
                new MultiLanguageBatchInput(documents)).Result;
            // Output the results to the CSV file
